**What this code covers**

- Complete event-driven e-commerce order processing
- In-memory event bus (Kafka-like)
- Event Sourcing pattern with multiple read projections
- Append-only event store
- Compensate in reverse order
- Failed saga (insufficient funds → rollback)
- Sync events to read model
- Queries (reads — fast, denormalized)

**Defines:** `Event`, `EventBus`, `OrderService`, `InventoryService`, `PaymentService`, `NotificationService`, `AnalyticsService`, `DomainEvent`, `EventStore`, `BankAccount`

### Example 1: Event-Driven Order Processing System

```python
"""
Complete event-driven e-commerce order processing
"""
import json
import time
from datetime import datetime
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Callable, Any
from collections import defaultdict
from enum import Enum
import uuid

# ─── Event Infrastructure ───
@dataclass
class Event:
    event_type: str
    data: Dict
    event_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    timestamp: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    source: str = ""
    version: int = 1

class EventBus:
    """In-memory event bus (Kafka-like)"""

    def __init__(self):
        self._subscribers: Dict[str, List[Callable]] = defaultdict(list)
        self._event_log: List[Event] = []
        self._dead_letter: List[tuple] = []

    def subscribe(self, event_type: str, handler: Callable):
        self._subscribers[event_type].append(handler)

    def publish(self, event: Event):
        self._event_log.append(event)
        handlers = self._subscribers.get(event_type := event.event_type, [])
        print(f"  📤 Published: {event_type} → {len(handlers)} handlers")

        for handler in handlers:
            try:
                handler(event)
            except Exception as e:
                self._dead_letter.append((event, str(e)))
                print(f"  ❌ Handler failed: {e}")

    def replay(self, from_index: int = 0):
        return self._event_log[from_index:]

# ─── Domain Services ───
class OrderService:
    def __init__(self, bus: EventBus):
        self.bus = bus
        self.orders = {}

    def place_order(self, user_id: str, items: list, total: float):
        order_id = f"ORD-{uuid.uuid4().hex[:8]}"
        self.orders[order_id] = {
            "order_id": order_id, "user_id": user_id,
            "items": items, "total": total, "status": "placed"
        }
        self.bus.publish(Event(
            event_type="OrderPlaced",
            data={"order_id": order_id, "user_id": user_id,
                  "items": items, "total": total},
            source="order-service"
        ))
        return order_id

class InventoryService:
    def __init__(self, bus: EventBus):
        self.bus = bus
        self.stock = {"laptop": 10, "mouse": 50, "keyboard": 30}
        bus.subscribe("OrderPlaced", self.handle_order)

    def handle_order(self, event: Event):
        items = event.data["items"]
        order_id = event.data["order_id"]
        can_fulfill = all(
            self.stock.get(item["product"], 0) >= item["qty"]
            for item in items
        )
        if can_fulfill:
            for item in items:
                self.stock[item["product"]] -= item["qty"]
            self.bus.publish(Event(
                event_type="InventoryReserved",
                data={"order_id": order_id, "items": items},
                source="inventory-service"
            ))
            print(f"  📦 Inventory reserved for {order_id}")
        else:
            self.bus.publish(Event(
                event_type="InventoryInsufficient",
                data={"order_id": order_id},
                source="inventory-service"
            ))

class PaymentService:
    def __init__(self, bus: EventBus):
        self.bus = bus
        bus.subscribe("InventoryReserved", self.process_payment)

    def process_payment(self, event: Event):
        order_id = event.data["order_id"]
        # Simulate payment
        self.bus.publish(Event(
            event_type="PaymentProcessed",
            data={"order_id": order_id, "status": "success"},
            source="payment-service"
        ))
        print(f"  💳 Payment processed for {order_id}")

class NotificationService:
    def __init__(self, bus: EventBus):
        self.bus = bus
        self.notifications = []
        bus.subscribe("OrderPlaced", self.on_order)
        bus.subscribe("PaymentProcessed", self.on_payment)
        bus.subscribe("InventoryInsufficient", self.on_stock_issue)

    def on_order(self, event: Event):
        self.notifications.append(f"Order {event.data['order_id']} received!")

    def on_payment(self, event: Event):
        self.notifications.append(f"Payment confirmed for {event.data['order_id']}")

    def on_stock_issue(self, event: Event):
        self.notifications.append(f"Sorry, order {event.data['order_id']} out of stock")

class AnalyticsService:
    def __init__(self, bus: EventBus):
        self.bus = bus
        self.metrics = {"orders": 0, "revenue": 0, "events_processed": 0}
        bus.subscribe("OrderPlaced", self.track)
        bus.subscribe("PaymentProcessed", self.track)

    def track(self, event: Event):
        self.metrics["events_processed"] += 1
        if event.event_type == "OrderPlaced":
            self.metrics["orders"] += 1
            self.metrics["revenue"] += event.data.get("total", 0)

# ─── Wire Everything ───
bus = EventBus()
orders = OrderService(bus)
inventory = InventoryService(bus)
payments = PaymentService(bus)
notifications = NotificationService(bus)
analytics = AnalyticsService(bus)

# Place orders
print("Order 1:")
orders.place_order("user1", [{"product": "laptop", "qty": 1}], 999.99)
print("\nOrder 2:")
orders.place_order("user2", [{"product": "mouse", "qty": 2}], 49.98)

print(f"\n📊 Analytics: {analytics.metrics}")
print(f"🔔 Notifications: {notifications.notifications}")
print(f"📦 Stock: {inventory.stock}")
```

### Example 2: Event Sourcing with Projections

```python
"""
Event Sourcing pattern with multiple read projections
"""
from dataclasses import dataclass, field
from typing import Dict, List, Optional
from datetime import datetime
import uuid

@dataclass
class DomainEvent:
    aggregate_id: str
    event_type: str
    data: Dict
    version: int
    timestamp: str = field(default_factory=lambda: datetime.utcnow().isoformat())

class EventStore:
    """Append-only event store"""

    def __init__(self):
        self._events: List[DomainEvent] = []
        self._projections: Dict[str, 'Projection'] = {}

    def append(self, event: DomainEvent):
        self._events.append(event)
        # Update all projections
        for proj in self._projections.values():
            proj.apply(event)

    def get_events(self, aggregate_id: str) -> List[DomainEvent]:
        return [e for e in self._events if e.aggregate_id == aggregate_id]

    def register_projection(self, name: str, projection: 'Projection'):
        self._projections[name] = projection
        # Replay existing events
        for event in self._events:
            projection.apply(event)

class BankAccount:
    """Aggregate that uses event sourcing"""

    def __init__(self, account_id: str, store: EventStore):
        self.account_id = account_id
        self.store = store
        self._version = 0

    def _emit(self, event_type: str, data: dict):
        self._version += 1
        event = DomainEvent(
            aggregate_id=self.account_id,
            event_type=event_type,
            data=data,
            version=self._version
        )
        self.store.append(event)

    def open(self, owner: str, initial_deposit: float = 0):
        self._emit("AccountOpened", {"owner": owner, "initial_deposit": initial_deposit})
        if initial_deposit > 0:
            self._emit("MoneyDeposited", {"amount": initial_deposit})

    def deposit(self, amount: float):
        if amount <= 0:
            raise ValueError("Deposit must be positive")
        self._emit("MoneyDeposited", {"amount": amount})

    def withdraw(self, amount: float):
        balance = self._get_balance()
        if amount > balance:
            self._emit("WithdrawalRejected", {"amount": amount, "balance": balance})
            raise ValueError(f"Insufficient funds: balance={balance}")
        self._emit("MoneyWithdrawn", {"amount": amount})

    def transfer(self, to_account: 'BankAccount', amount: float):
        self.withdraw(amount)
        to_account.deposit(amount)
        self._emit("TransferSent", {"to": to_account.account_id, "amount": amount})

    def _get_balance(self) -> float:
        balance = 0
        for event in self.store.get_events(self.account_id):
            if event.event_type == "MoneyDeposited":
                balance += event.data["amount"]
            elif event.event_type == "MoneyWithdrawn":
                balance -= event.data["amount"]
        return balance

# ─── Projections (Read Models) ───
class Projection:
    def apply(self, event: DomainEvent):
        raise NotImplementedError

class BalanceProjection(Projection):
    """Projects current balance per account"""

    def __init__(self):
        self.balances: Dict[str, float] = {}

    def apply(self, event: DomainEvent):
        aid = event.aggregate_id
        if event.event_type == "MoneyDeposited":
            self.balances[aid] = self.balances.get(aid, 0) + event.data["amount"]
        elif event.event_type == "MoneyWithdrawn":
            self.balances[aid] = self.balances.get(aid, 0) - event.data["amount"]

    def get_balance(self, account_id: str) -> float:
        return self.balances.get(account_id, 0)

class TransactionHistoryProjection(Projection):
    """Projects transaction history per account"""

    def __init__(self):
        self.history: Dict[str, List] = {}

    def apply(self, event: DomainEvent):
        if event.event_type in ("MoneyDeposited", "MoneyWithdrawn", "TransferSent"):
            self.history.setdefault(event.aggregate_id, []).append({
                "type": event.event_type,
                "amount": event.data.get("amount"),
                "timestamp": event.timestamp,
                "version": event.version
            })

class DailyVolumeProjection(Projection):
    """Projects daily transaction volume (analytics)"""

    def __init__(self):
        self.daily_volume: Dict[str, float] = {}

    def apply(self, event: DomainEvent):
        if event.event_type in ("MoneyDeposited", "MoneyWithdrawn"):
            day = event.timestamp[:10]
            self.daily_volume[day] = self.daily_volume.get(day, 0) + event.data["amount"]

# ─── Demo ───
store = EventStore()
balance_view = BalanceProjection()
history_view = TransactionHistoryProjection()
volume_view = DailyVolumeProjection()

store.register_projection("balances", balance_view)
store.register_projection("history", history_view)
store.register_projection("volume", volume_view)

# Create accounts
alice = BankAccount("ACC-001", store)
bob = BankAccount("ACC-002", store)

alice.open("Alice", initial_deposit=1000)
bob.open("Bob", initial_deposit=500)

alice.deposit(200)
alice.withdraw(150)
alice.transfer(bob, 300)

print(f"Alice balance: ${balance_view.get_balance('ACC-001')}")
print(f"Bob balance: ${balance_view.get_balance('ACC-002')}")
print(f"\nAlice history:")
for tx in history_view.history.get("ACC-001", []):
    print(f"  {tx['type']}: ${tx['amount']}")
print(f"\nAll events in store: {len(store._events)}")
```

### Example 3: Saga Pattern for Distributed Transactions

```python
"""
Saga pattern — orchestrate distributed transactions with compensations
"""
from dataclasses import dataclass, field
from typing import Dict, List, Callable, Optional
from enum import Enum
import uuid

class SagaState(Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    COMPENSATING = "compensating"
    FAILED = "failed"

@dataclass
class SagaStep:
    name: str
    action: Callable
    compensation: Callable
    status: str = "pending"
    result: any = None
    error: str = ""

class SagaOrchestrator:
    """Orchestrates distributed transactions with automatic rollback"""

    def __init__(self, name: str):
        self.saga_id = str(uuid.uuid4())[:8]
        self.name = name
        self.steps: List[SagaStep] = []
        self.state = SagaState.PENDING
        self.context: Dict = {}

    def add_step(self, name: str, action: Callable, compensation: Callable):
        self.steps.append(SagaStep(name=name, action=action, compensation=compensation))

    def execute(self) -> dict:
        self.state = SagaState.RUNNING
        completed_steps = []
        print(f"\n🔄 Saga '{self.name}' [{self.saga_id}] started")

        for i, step in enumerate(self.steps):
            try:
                print(f"  Step {i+1}/{len(self.steps)}: {step.name}...")
                step.result = step.action(self.context)
                step.status = "completed"
                completed_steps.append(step)
                print(f"    ✓ {step.name} succeeded")
            except Exception as e:
                step.status = "failed"
                step.error = str(e)
                print(f"    ✗ {step.name} failed: {e}")

                # Compensate in reverse order
                self.state = SagaState.COMPENSATING
                print(f"  ⏪ Compensating {len(completed_steps)} steps...")
                for comp_step in reversed(completed_steps):
                    try:
                        comp_step.compensation(self.context)
                        comp_step.status = "compensated"
                        print(f"    ↩ {comp_step.name} compensated")
                    except Exception as ce:
                        print(f"    ⚠ Compensation failed for {comp_step.name}: {ce}")

                self.state = SagaState.FAILED
                return {"success": False, "failed_at": step.name, "error": str(e)}

        self.state = SagaState.COMPLETED
        print(f"  ✅ Saga completed successfully")
        return {"success": True, "steps_completed": len(self.steps)}

# ─── Services ───
class OrderDB:
    orders = {}

class InventoryDB:
    stock = {"laptop": 5, "mouse": 20}

class PaymentDB:
    balances = {"user1": 2000, "user2": 50}

# Saga steps
def create_order(ctx):
    order_id = f"ORD-{uuid.uuid4().hex[:6]}"
    OrderDB.orders[order_id] = {"id": order_id, "status": "created",
                                 "items": ctx["items"], "total": ctx["total"]}
    ctx["order_id"] = order_id
    return order_id

def cancel_order(ctx):
    OrderDB.orders.pop(ctx.get("order_id"), None)

def reserve_inventory(ctx):
    for item in ctx["items"]:
        if InventoryDB.stock.get(item["product"], 0) < item["qty"]:
            raise Exception(f"Out of stock: {item['product']}")
        InventoryDB.stock[item["product"]] -= item["qty"]

def release_inventory(ctx):
    for item in ctx["items"]:
        InventoryDB.stock[item["product"]] = InventoryDB.stock.get(item["product"], 0) + item["qty"]

def process_payment(ctx):
    user = ctx["user_id"]
    total = ctx["total"]
    if PaymentDB.balances.get(user, 0) < total:
        raise Exception(f"Insufficient funds for {user}")
    PaymentDB.balances[user] -= total

def refund_payment(ctx):
    PaymentDB.balances[ctx["user_id"]] = PaymentDB.balances.get(ctx["user_id"], 0) + ctx["total"]

# Successful saga
saga1 = SagaOrchestrator("Place Order")
saga1.context = {"user_id": "user1", "items": [{"product": "laptop", "qty": 1}], "total": 999}
saga1.add_step("Create Order", create_order, cancel_order)
saga1.add_step("Reserve Inventory", reserve_inventory, release_inventory)
saga1.add_step("Process Payment", process_payment, refund_payment)
saga1.execute()

# Failed saga (insufficient funds → rollback)
saga2 = SagaOrchestrator("Place Order (will fail)")
saga2.context = {"user_id": "user2", "items": [{"product": "mouse", "qty": 1}], "total": 100}
saga2.add_step("Create Order", create_order, cancel_order)
saga2.add_step("Reserve Inventory", reserve_inventory, release_inventory)
saga2.add_step("Process Payment", process_payment, refund_payment)
saga2.execute()

print(f"\nInventory after sagas: {InventoryDB.stock}")
print(f"Balances after sagas: {PaymentDB.balances}")
```

### Example 4: Event-Driven Data Pipeline

```python
"""
Event-driven data pipeline with backpressure and dead-letter queue
"""
from collections import deque
from threading import Lock
from typing import Dict, List, Callable, Optional
from dataclasses import dataclass, field
from datetime import datetime
import time

@dataclass
class PipelineEvent:
    data: Dict
    topic: str
    key: str = ""
    timestamp: float = field(default_factory=time.time)
    retries: int = 0
    max_retries: int = 3

class EventChannel:
    """Buffered event channel with backpressure"""

    def __init__(self, name: str, max_buffer: int = 1000):
        self.name = name
        self.buffer: deque = deque(maxlen=max_buffer)
        self.max_buffer = max_buffer
        self._lock = Lock()
        self.metrics = {"produced": 0, "consumed": 0, "dropped": 0}

    def produce(self, event: PipelineEvent) -> bool:
        with self._lock:
            if len(self.buffer) >= self.max_buffer:
                self.metrics["dropped"] += 1
                return False  # Backpressure signal
            self.buffer.append(event)
            self.metrics["produced"] += 1
            return True

    def consume(self) -> Optional[PipelineEvent]:
        with self._lock:
            if self.buffer:
                self.metrics["consumed"] += 1
                return self.buffer.popleft()
            return None

    @property
    def utilization(self) -> float:
        return len(self.buffer) / self.max_buffer

class EventPipeline:
    """Multi-stage event processing pipeline"""

    def __init__(self):
        self.stages: List[Dict] = []
        self.dlq: List[PipelineEvent] = []
        self.channels: Dict[str, EventChannel] = {}

    def add_stage(self, name: str, processor: Callable,
                  input_channel: str, output_channel: str = None,
                  buffer_size: int = 100):
        if input_channel not in self.channels:
            self.channels[input_channel] = EventChannel(input_channel, buffer_size)
        if output_channel and output_channel not in self.channels:
            self.channels[output_channel] = EventChannel(output_channel, buffer_size)

        self.stages.append({
            "name": name, "processor": processor,
            "input": input_channel, "output": output_channel
        })

    def ingest(self, events: List[Dict], topic: str):
        channel = self.channels.get(topic)
        if not channel:
            return
        for data in events:
            event = PipelineEvent(data=data, topic=topic, key=str(data.get("id", "")))
            if not channel.produce(event):
                print(f"⚠ Backpressure on {topic}! Buffer full.")

    def process(self, max_iterations: int = 100):
        """Process events through all stages"""
        for iteration in range(max_iterations):
            processed_any = False

            for stage in self.stages:
                input_ch = self.channels[stage["input"]]
                output_ch = self.channels.get(stage["output"]) if stage["output"] else None

                event = input_ch.consume()
                if event is None:
                    continue

                processed_any = True
                try:
                    result = stage["processor"](event.data)
                    if result and output_ch:
                        output_event = PipelineEvent(
                            data=result, topic=stage["output"],
                            key=event.key
                        )
                        output_ch.produce(output_event)
                except Exception as e:
                    event.retries += 1
                    if event.retries >= event.max_retries:
                        self.dlq.append(event)
                    else:
                        input_ch.produce(event)  # Re-queue for retry

            if not processed_any:
                break

    def status(self) -> Dict:
        return {
            "channels": {
                name: {
                    "buffered": len(ch.buffer),
                    "utilization": f"{ch.utilization:.1%}",
                    **ch.metrics
                }
                for name, ch in self.channels.items()
            },
            "dead_letter_queue": len(self.dlq),
            "stages": len(self.stages)
        }

# ─── Build Pipeline ───
pipeline = EventPipeline()

def parse_event(data):
    """Stage 1: Parse and validate"""
    if not data.get("user_id"):
        raise ValueError("Missing user_id")
    return {**data, "parsed": True, "parsed_at": datetime.utcnow().isoformat()}

def enrich_event(data):
    """Stage 2: Enrich with computed fields"""
    user_segments = {"u1": "premium", "u2": "regular", "u3": "new"}
    return {
        **data,
        "segment": user_segments.get(data["user_id"], "unknown"),
        "enriched": True
    }

def aggregate_event(data):
    """Stage 3: Prepare for loading"""
    return {
        "user_id": data["user_id"],
        "segment": data.get("segment"),
        "amount": data.get("amount", 0),
        "ready_for_load": True
    }

pipeline.add_stage("parse", parse_event, "raw", "parsed", buffer_size=50)
pipeline.add_stage("enrich", enrich_event, "parsed", "enriched", buffer_size=50)
pipeline.add_stage("aggregate", aggregate_event, "enriched", "output", buffer_size=50)

# Ingest data
events = [
    {"id": 1, "user_id": "u1", "amount": 100, "action": "purchase"},
    {"id": 2, "user_id": "u2", "amount": 50, "action": "purchase"},
    {"id": 3, "user_id": None, "amount": 25, "action": "click"},  # Bad data
    {"id": 4, "user_id": "u3", "amount": 200, "action": "purchase"},
]
pipeline.ingest(events, "raw")
pipeline.process()

import json
print(json.dumps(pipeline.status(), indent=2))
print(f"DLQ events: {len(pipeline.dlq)}")
```

### Example 5: CQRS Implementation

```python
"""
CQRS — separate write and read models with event synchronization
"""
from dataclasses import dataclass, field
from typing import Dict, List, Optional
from datetime import datetime
import uuid

# ─── Write Side (Commands) ───
@dataclass
class Command:
    command_type: str
    data: Dict
    command_id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])

class WriteModel:
    """Handles commands, emits events, stores in normalized form"""

    def __init__(self):
        self.products: Dict[str, Dict] = {}
        self.orders: Dict[str, Dict] = {}
        self._events: List[Dict] = []

    def handle(self, command: Command) -> Dict:
        handler = getattr(self, f"_handle_{command.command_type}", None)
        if not handler:
            raise ValueError(f"Unknown command: {command.command_type}")
        return handler(command.data)

    def _handle_create_product(self, data):
        pid = data["product_id"]
        self.products[pid] = {
            "product_id": pid, "name": data["name"],
            "price": data["price"], "stock": data.get("stock", 0)
        }
        self._emit("ProductCreated", data)
        return {"product_id": pid}

    def _handle_place_order(self, data):
        oid = f"ORD-{uuid.uuid4().hex[:6]}"
        items = data["items"]
        total = sum(
            self.products[i["product_id"]]["price"] * i["qty"]
            for i in items
        )
        self.orders[oid] = {
            "order_id": oid, "user_id": data["user_id"],
            "items": items, "total": total, "status": "placed"
        }
        for item in items:
            self.products[item["product_id"]]["stock"] -= item["qty"]

        self._emit("OrderPlaced", {"order_id": oid, "user_id": data["user_id"],
                                    "items": items, "total": total})
        return {"order_id": oid, "total": total}

    def _emit(self, event_type, data):
        self._events.append({
            "event_type": event_type, "data": data,
            "timestamp": datetime.utcnow().isoformat()
        })

    def get_events_since(self, index: int) -> List[Dict]:
        return self._events[index:]

# ─── Read Side (Queries) ───
class ReadModel:
    """Optimized for queries — denormalized, eventually consistent"""

    def __init__(self):
        self._product_catalog: Dict[str, Dict] = {}
        self._order_history: Dict[str, List] = {}  # by user
        self._top_products: Dict[str, int] = {}
        self._revenue_by_user: Dict[str, float] = {}
        self._last_event_index = 0

    def sync(self, events: List[Dict]):
        """Sync from write model events"""
        for event in events:
            handler = getattr(self, f"_on_{event['event_type']}", None)
            if handler:
                handler(event["data"])
        self._last_event_index += len(events)

    def _on_ProductCreated(self, data):
        self._product_catalog[data["product_id"]] = {
            "name": data["name"], "price": data["price"],
            "stock": data.get("stock", 0)
        }

    def _on_OrderPlaced(self, data):
        user = data["user_id"]
        self._order_history.setdefault(user, []).append({
            "order_id": data["order_id"],
            "total": data["total"],
            "items_count": sum(i["qty"] for i in data["items"])
        })
        self._revenue_by_user[user] = self._revenue_by_user.get(user, 0) + data["total"]
        for item in data["items"]:
            pid = item["product_id"]
            self._top_products[pid] = self._top_products.get(pid, 0) + item["qty"]

    # ─── Query Methods ───
    def get_catalog(self) -> Dict:
        return self._product_catalog

    def get_user_orders(self, user_id: str) -> List:
        return self._order_history.get(user_id, [])

    def get_top_products(self, limit: int = 5) -> List:
        sorted_products = sorted(self._top_products.items(),
                                key=lambda x: x[1], reverse=True)
        return sorted_products[:limit]

    def get_user_spend(self, user_id: str) -> float:
        return self._revenue_by_user.get(user_id, 0)

# ─── Sync Mechanism ───
class EventSynchronizer:
    def __init__(self, write: WriteModel, read: ReadModel):
        self.write = write
        self.read = read

    def sync(self):
        new_events = self.write.get_events_since(self.read._last_event_index)
        if new_events:
            self.read.sync(new_events)
            print(f"Synced {len(new_events)} events to read model")

# ─── Demo ───
write = WriteModel()
read = ReadModel()
sync = EventSynchronizer(write, read)

